//! Every melee attack's blade path, baked from its animation.
//!
//! GENERATED by `make bake-hits` (client/hit_bake_tests.rs). Do not edit:
//! change the clip, the attack clip row, the weapon or the duration and
//! bake again. Samples are grip xyz then tip xyz in the attacker's frame
//! (feet at the origin, facing -Z), one per fixed step.
use super::sweep::HitTrack;
use crate::simulation::{ActionKind, MeleeStage, TrackId, WeaponPair};

pub(super) fn of(track: TrackId) -> Option<&'static HitTrack> {
    Some(match track {
        TrackId::PlayerMelee { pair: WeaponPair::HammerMusket, stage: MeleeStage::One } => &TRACK_0,
        TrackId::PlayerMelee { pair: WeaponPair::HammerMusket, stage: MeleeStage::Two } => &TRACK_1,
        TrackId::PlayerMelee { pair: WeaponPair::HammerMusket, stage: MeleeStage::Three } => &TRACK_2,
        TrackId::PlayerMelee { pair: WeaponPair::ChainAxeBow, stage: MeleeStage::One } => &TRACK_3,
        TrackId::PlayerMelee { pair: WeaponPair::ChainAxeBow, stage: MeleeStage::Two } => &TRACK_4,
        TrackId::PlayerMelee { pair: WeaponPair::ChainAxeBow, stage: MeleeStage::Three } => &TRACK_5,
        TrackId::PlayerSkill(ActionKind::HammerSlam) => &TRACK_6,
        TrackId::PlayerSkill(ActionKind::ChainSweep) => &TRACK_7,
        TrackId::Boss { stage: MeleeStage::One } => &TRACK_8,
        TrackId::Boss { stage: MeleeStage::Two } => &TRACK_9,
        TrackId::Boss { stage: MeleeStage::Three } => &TRACK_10,
        TrackId::Enemy => &TRACK_11,
        TrackId::PlayerSkill(_) => return None,
    })
}

